/* ClipCast Design System */
:root {
  --primary: #6D5BFF;
  --primary-dark: #4F3DE8;
  --primary-light: #8B7BFF;
  --indigo: #1868DB;
  --accent: #FF613D;
  --dark: #1A1B23;
  --text: #292A2E;
  --muted: #6B7280;
  --border: #E5E7EB;
  --bg-soft: #F7F6FE;
  --bg-tint: #FAF9FF;
  --gradient: linear-gradient(135deg, #6D5BFF 0%, #9B7BFF 50%, #FF613D 100%);
  --gradient-soft: linear-gradient(135deg, #F4F1FF 0%, #FFF4F0 100%);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--text);
  background: #fff;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

.container { max-width: 1240px; margin: 0 auto; padding: 0 24px; }
.container-narrow { max-width: 1040px; margin: 0 auto; padding: 0 24px; }

/* Typography */
h1, h2, h3, h4 { font-family: 'Plus Jakarta Sans', sans-serif; color: var(--dark); letter-spacing: -0.02em; line-height: 1.15; font-weight: 800; }
h1 { font-size: clamp(2.5rem, 5vw, 4.25rem); }
h2 { font-size: clamp(2rem, 3.5vw, 3rem); }
h3 { font-size: clamp(1.5rem, 2.2vw, 2rem); }
h4 { font-size: 1.25rem; font-weight: 700; }

.eyebrow { display: inline-flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: var(--primary); padding: 6px 14px; background: rgba(109,91,255,0.1); border-radius: 999px; }

/* Nav */
.nav {
  position: sticky; top: 0; z-index: 50;
  background: rgba(255,255,255,0.85);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}
.nav-inner { display: flex; align-items: center; justify-content: space-between; height: 72px; }
.logo { display: flex; align-items: center; gap: 8px; font-weight: 800; font-size: 22px; color: var(--dark); }
.logo-mark {
  width: 32px; height: 32px; border-radius: 8px;
  background: var(--gradient);
  display: grid; place-items: center;
  position: relative;
}
.logo-mark::after {
  content: ""; width: 0; height: 0;
  border-left: 8px solid white;
  border-top: 5px solid transparent;
  border-bottom: 5px solid transparent;
  margin-left: 2px;
}
.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links a { font-weight: 600; color: var(--text); font-size: 15px; transition: color .15s; }
.nav-links a:hover { color: var(--primary); }
.nav-cta { display: flex; align-items: center; gap: 12px; }

@media (max-width: 900px) {
  .nav-links { display: none; }
}

/* Buttons */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 12px 22px; border-radius: 12px; font-weight: 700; font-size: 15px; transition: all .2s ease; white-space: nowrap; }
.btn-primary { background: var(--dark); color: white; }
.btn-primary:hover { background: var(--primary); transform: translateY(-1px); box-shadow: 0 12px 28px -8px rgba(109,91,255,.45); }
.btn-accent { background: var(--gradient); color: white; }
.btn-accent:hover { transform: translateY(-1px); box-shadow: 0 14px 32px -10px rgba(109,91,255,.55); }
.btn-ghost { color: var(--dark); }
.btn-ghost:hover { color: var(--primary); }
.btn-outline { background: white; color: var(--dark); border: 2px solid var(--dark); }
.btn-outline:hover { background: var(--dark); color: white; }
.btn-lg { padding: 16px 28px; font-size: 16px; border-radius: 14px; }

/* Sections */
section { padding: 80px 0; }
.section-tight { padding: 56px 0; }
.section-soft { background: var(--bg-soft); }
.section-tint { background: var(--bg-tint); }
.section-dark { background: var(--dark); color: white; }
.section-dark h1, .section-dark h2, .section-dark h3, .section-dark h4 { color: white; }

/* Hero */
.hero { padding: 80px 0 100px; position: relative; overflow: hidden; }
.hero-bg {
  position: absolute; inset: 0; z-index: -1;
  background:
    radial-gradient(ellipse 80% 50% at 20% 20%, rgba(109,91,255,.18), transparent 60%),
    radial-gradient(ellipse 60% 50% at 90% 80%, rgba(255,97,61,.14), transparent 60%),
    linear-gradient(180deg, #FBFAFF 0%, #FFFFFF 100%);
}
.hero-grid { display: grid; grid-template-columns: 1.1fr 1fr; gap: 60px; align-items: center; }
.hero h1 span.grad { background: var(--gradient); -webkit-background-clip: text; background-clip: text; color: transparent; }
.hero p { font-size: 19px; color: var(--muted); margin: 24px 0 32px; max-width: 540px; }
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }
.hero-meta { margin-top: 24px; font-size: 14px; color: var(--muted); display: flex; gap: 18px; }
.hero-meta span::before { content: "✓"; color: var(--primary); margin-right: 6px; font-weight: 800; }

@media (max-width: 900px) {
  .hero-grid { grid-template-columns: 1fr; }
}

/* Mock video card */
.mock-video {
  position: relative; aspect-ratio: 16/10;
  background: var(--gradient);
  border-radius: 24px;
  padding: 14px;
  box-shadow: 0 30px 80px -20px rgba(109,91,255,.5);
  transform: rotate(-1.5deg);
  transition: transform .4s ease;
}
.mock-video:hover { transform: rotate(0); }
.mock-video-inner {
  background: linear-gradient(135deg, #2d2740 0%, #1a1530 100%);
  border-radius: 16px; height: 100%;
  position: relative; overflow: hidden;
  display: grid; place-items: center;
}
.mock-video-inner::before {
  content: ""; position: absolute; inset: 0;
  background:
    radial-gradient(circle at 70% 30%, rgba(255,97,61,.4), transparent 50%),
    radial-gradient(circle at 30% 70%, rgba(109,91,255,.4), transparent 50%);
}
.mock-play {
  position: relative; z-index: 2;
  width: 84px; height: 84px; border-radius: 50%;
  background: white; display: grid; place-items: center;
  box-shadow: 0 20px 50px rgba(0,0,0,.3);
}
.mock-play::after {
  content: ""; width: 0; height: 0;
  border-left: 24px solid var(--primary);
  border-top: 14px solid transparent;
  border-bottom: 14px solid transparent;
  margin-left: 6px;
}
.mock-cam {
  position: absolute; bottom: 28px; left: 28px; z-index: 3;
  width: 90px; height: 90px; border-radius: 50%;
  background: linear-gradient(135deg, #FFB199, #FF613D);
  border: 4px solid white;
  box-shadow: 0 10px 30px rgba(0,0,0,.25);
}
.mock-toolbar {
  position: absolute; bottom: 28px; right: 28px; z-index: 3;
  display: flex; gap: 8px;
  background: rgba(255,255,255,.95); padding: 8px; border-radius: 999px;
  backdrop-filter: blur(8px);
}
.mock-toolbar i { width: 32px; height: 32px; border-radius: 50%; background: var(--bg-soft); display: grid; place-items: center; font-style: normal; }

/* Logo bar */
.logo-bar { padding: 60px 0; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
.logo-bar p { text-align: center; color: var(--muted); margin-bottom: 28px; font-weight: 600; font-size: 14px; letter-spacing: 0.05em; text-transform: uppercase; }
.logo-row { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 28px; }
.logo-row .brand { font-weight: 800; font-size: 22px; color: var(--muted); opacity: .65; letter-spacing: -0.02em; transition: opacity .2s; }
.logo-row .brand:hover { opacity: 1; }

/* Cards */
.card {
  background: white; border: 1px solid var(--border);
  border-radius: 20px; padding: 32px;
  transition: transform .25s ease, box-shadow .25s ease, border-color .25s;
}
.card:hover { transform: translateY(-3px); box-shadow: 0 20px 50px -20px rgba(26,27,35,.18); border-color: rgba(109,91,255,.3); }
.card-icon {
  width: 56px; height: 56px; border-radius: 14px;
  background: var(--gradient-soft);
  display: grid; place-items: center;
  font-size: 24px; margin-bottom: 20px;
}
.card h3 { font-size: 22px; margin-bottom: 8px; }
.card p { color: var(--muted); }

/* Section header */
.section-head { text-align: center; max-width: 720px; margin: 0 auto 56px; }
.section-head .eyebrow { margin-bottom: 16px; }
.section-head p { color: var(--muted); margin-top: 16px; font-size: 18px; }

/* Feature row */
.feature-row { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
.feature-row.flip { direction: rtl; }
.feature-row.flip > * { direction: ltr; }
.feature-row img, .feature-row .feature-visual { width: 100%; border-radius: 24px; }
.feature-row h2 { margin-bottom: 16px; }
.feature-row p { color: var(--muted); font-size: 17px; margin-bottom: 24px; }
@media (max-width: 900px) {
  .feature-row { grid-template-columns: 1fr; gap: 36px; }
  .feature-row.flip { direction: ltr; }
}

.feature-visual {
  aspect-ratio: 4/3; background: var(--gradient-soft);
  border: 1px solid var(--border);
  position: relative; overflow: hidden;
  display: grid; place-items: center;
}
.fv-tag {
  position: absolute; top: 24px; left: 24px;
  background: white; padding: 8px 16px; border-radius: 999px;
  font-size: 12px; font-weight: 700; color: var(--primary);
  box-shadow: 0 6px 20px rgba(0,0,0,.08);
}
.fv-circle {
  width: 60%; aspect-ratio: 1; border-radius: 50%;
  background: var(--gradient); opacity: .7;
  position: relative;
}
.fv-window {
  width: 80%; aspect-ratio: 16/9; background: white;
  border-radius: 16px; box-shadow: 0 30px 60px -20px rgba(0,0,0,.18);
  overflow: hidden;
}
.fv-window-bar { display: flex; gap: 6px; padding: 12px; border-bottom: 1px solid var(--border); }
.fv-window-bar i { width: 10px; height: 10px; border-radius: 50%; background: #FF6058; }
.fv-window-bar i:nth-child(2) { background: #FFBD2E; }
.fv-window-bar i:nth-child(3) { background: #28CA41; }
.fv-window-body { padding: 18px; display: grid; gap: 10px; }
.fv-bar { height: 10px; border-radius: 5px; background: var(--bg-soft); }
.fv-bar.lg { background: var(--gradient); width: 70%; }
.fv-bar.md { width: 90%; }
.fv-bar.sm { width: 50%; }

/* Grid */
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
@media (max-width: 900px) {
  .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .grid-2 { grid-template-columns: 1fr; }
}
@media (max-width: 1080px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
}

/* Use case card */
.usecase {
  padding: 28px; border-radius: 20px;
  background: white; border: 1px solid var(--border);
  display: flex; flex-direction: column; gap: 14px;
  transition: all .25s;
}
.usecase:hover { border-color: var(--primary); transform: translateY(-3px); }
.usecase .pill { font-size: 13px; font-weight: 700; padding: 4px 10px; border-radius: 999px; align-self: flex-start; }
.uc-sales .pill { background: #FFE6DD; color: #C73E1D; }
.uc-eng .pill { background: #DBEAFE; color: #1E40AF; }
.uc-support .pill { background: #DCFCE7; color: #15803D; }
.uc-design .pill { background: #FAE8FF; color: #86198F; }
.usecase h3 { font-size: 22px; }
.usecase p { color: var(--muted); }

/* Features list grid */
.feat-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.feat-cell { padding: 24px; border-radius: 16px; background: white; border: 1px solid var(--border); display: flex; flex-direction: column; gap: 10px; }
.feat-cell .ico {
  width: 40px; height: 40px; border-radius: 10px;
  background: var(--gradient-soft);
  display: grid; place-items: center;
}
.feat-cell h4 { font-size: 16px; }
@media (max-width: 1080px) { .feat-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .feat-grid { grid-template-columns: 1fr; } }

/* Stats */
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; text-align: center; }
.stat .num {
  font-size: clamp(3rem, 6vw, 5rem); font-weight: 800;
  background: var(--gradient); -webkit-background-clip: text; background-clip: text; color: transparent;
  letter-spacing: -0.04em; line-height: 1;
}
.stat p { color: var(--muted); margin-top: 8px; font-size: 17px; }
@media (max-width: 900px) { .stats-grid { grid-template-columns: 1fr; } }

/* Testimonials */
.test-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
@media (max-width: 1080px) { .test-grid { grid-template-columns: 1fr; } }
.testimonial {
  padding: 32px; border-radius: 20px;
  background: white; border: 1px solid var(--border);
  display: flex; flex-direction: column; gap: 20px;
}
.testimonial p.quote { font-size: 17px; line-height: 1.6; color: var(--text); }
.testimonial .author { display: flex; align-items: center; gap: 12px; margin-top: auto; }
.testimonial .avatar {
  width: 48px; height: 48px; border-radius: 50%;
  background: var(--gradient); color: white; display: grid; place-items: center;
  font-weight: 700;
}
.testimonial .name { font-weight: 700; color: var(--dark); }
.testimonial .role { font-size: 13px; color: var(--muted); }

/* CTA banner */
.cta-banner {
  border-radius: 32px; padding: 80px 48px;
  background: var(--gradient); color: white;
  text-align: center; position: relative; overflow: hidden;
}
.cta-banner::before {
  content: ""; position: absolute; inset: 0;
  background: radial-gradient(circle at 80% 20%, rgba(255,255,255,.2), transparent 50%);
}
.cta-banner h2 { color: white; margin-bottom: 16px; position: relative; }
.cta-banner p { font-size: 18px; opacity: .9; margin-bottom: 32px; position: relative; }
.cta-banner .btn { background: white; color: var(--dark); position: relative; }
.cta-banner .btn:hover { background: var(--dark); color: white; }

/* Footer */
.footer { background: #0F1018; color: #C9C9D6; padding: 80px 0 40px; }
.footer h4 { font-size: 14px; text-transform: uppercase; letter-spacing: 0.08em; color: white; margin-bottom: 18px; font-weight: 700; }
.footer-grid { display: grid; grid-template-columns: 1.5fr repeat(5, 1fr); gap: 40px; padding-bottom: 48px; border-bottom: 1px solid rgba(255,255,255,.1); }
.footer-grid ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-grid a { color: #9696A6; font-size: 14px; transition: color .15s; }
.footer-grid a:hover { color: white; }
.footer .logo { color: white; margin-bottom: 16px; }
.footer-bottom { padding-top: 32px; display: flex; justify-content: space-between; flex-wrap: wrap; gap: 16px; font-size: 13px; color: #6E6E80; }
@media (max-width: 1080px) { .footer-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .footer-grid { grid-template-columns: 1fr; } }

/* Pricing */
.billing-toggle { display: inline-flex; align-items: center; gap: 12px; background: var(--bg-soft); padding: 6px; border-radius: 999px; }
.billing-toggle button {
  padding: 10px 22px; border-radius: 999px;
  font-weight: 700; color: var(--muted); font-size: 14px;
  transition: all .2s;
}
.billing-toggle button.active { background: white; color: var(--dark); box-shadow: 0 2px 10px rgba(0,0,0,.06); }
.save-badge { display: inline-flex; padding: 4px 10px; background: #FFE6DD; color: var(--accent); border-radius: 999px; font-size: 12px; font-weight: 700; margin-left: 4px; }

.plan-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; align-items: stretch; }
@media (max-width: 1080px) { .plan-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .plan-grid { grid-template-columns: 1fr; } }
.plan {
  padding: 32px 24px; border-radius: 20px;
  background: white; border: 1px solid var(--border);
  display: flex; flex-direction: column; gap: 20px;
  position: relative;
}
.plan.popular { border-color: var(--primary); border-width: 2px; box-shadow: 0 30px 60px -20px rgba(109,91,255,.3); }
.plan-tag { position: absolute; top: -14px; left: 50%; transform: translateX(-50%); background: var(--gradient); color: white; padding: 6px 14px; border-radius: 999px; font-size: 12px; font-weight: 700; letter-spacing: 0.05em; }
.plan h3 { font-size: 20px; }
.plan .price { display: flex; align-items: baseline; gap: 4px; }
.plan .price .amount { font-size: 44px; font-weight: 800; color: var(--dark); letter-spacing: -0.03em; }
.plan .price .unit { color: var(--muted); font-size: 14px; font-weight: 600; }
.plan .desc { color: var(--muted); font-size: 14px; min-height: 42px; }
.plan ul { list-style: none; display: flex; flex-direction: column; gap: 12px; }
.plan ul li { font-size: 14px; color: var(--text); display: flex; gap: 10px; }
.plan ul li::before { content: "✓"; color: var(--primary); font-weight: 800; flex-shrink: 0; }
.plan .btn { width: 100%; }

/* Slider */
.slider-card {
  background: white; border: 1px solid var(--border);
  border-radius: 20px; padding: 28px;
  display: flex; flex-direction: column; gap: 16px; max-width: 640px; margin: 0 auto;
}
.slider-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; }
.slider-row label { font-weight: 700; }
.slider-value { font-weight: 800; color: var(--primary); font-size: 18px; }
input[type="range"] {
  -webkit-appearance: none; appearance: none;
  width: 100%; height: 6px; border-radius: 999px;
  background: linear-gradient(90deg, var(--primary) 0%, var(--primary) var(--val,30%), #E5E7EB var(--val,30%), #E5E7EB 100%);
  outline: none;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none; appearance: none;
  width: 24px; height: 24px; border-radius: 50%;
  background: white; border: 3px solid var(--primary);
  cursor: pointer; box-shadow: 0 4px 10px rgba(109,91,255,.3);
}
input[type="range"]::-moz-range-thumb {
  width: 24px; height: 24px; border-radius: 50%;
  background: white; border: 3px solid var(--primary); cursor: pointer;
}
.slider-result { font-size: 14px; color: var(--muted); padding-top: 10px; border-top: 1px solid var(--border); }
.slider-result strong { color: var(--dark); }

/* Comparison Table */
.comp-table-wrapper { overflow-x: auto; border-radius: 20px; border: 1px solid var(--border); background: white; }
.comp-table { width: 100%; border-collapse: collapse; min-width: 720px; }
.comp-table th, .comp-table td { padding: 16px 18px; text-align: left; border-bottom: 1px solid var(--border); font-size: 14px; }
.comp-table th { background: var(--bg-soft); font-weight: 700; color: var(--dark); font-size: 13px; text-transform: uppercase; letter-spacing: 0.05em; }
.comp-table td:first-child { font-weight: 600; color: var(--dark); }
.comp-table .check { color: var(--primary); font-weight: 800; }
.comp-table .dash { color: #C9C9D0; }
.comp-table tr.section-row td { background: var(--bg-tint); font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; font-size: 12px; color: var(--primary); }
.comp-collapse { max-height: 480px; overflow: hidden; transition: max-height .4s ease; position: relative; }
.comp-collapse.expanded { max-height: 4000px; }
.comp-fade { position: absolute; bottom: 0; left: 0; right: 0; height: 100px; background: linear-gradient(to top, white, transparent); pointer-events: none; transition: opacity .3s; }
.comp-collapse.expanded .comp-fade { opacity: 0; }

/* FAQ */
.faq-list { display: flex; flex-direction: column; gap: 12px; max-width: 820px; margin: 0 auto; }
.faq-item { background: white; border: 1px solid var(--border); border-radius: 14px; overflow: hidden; transition: border-color .2s; }
.faq-item.open { border-color: var(--primary); }
.faq-q { width: 100%; padding: 22px 24px; display: flex; justify-content: space-between; align-items: center; gap: 16px; font-weight: 700; font-size: 17px; text-align: left; color: var(--dark); }
.faq-q .chev { transition: transform .25s; flex-shrink: 0; color: var(--primary); font-size: 22px; line-height: 1; }
.faq-item.open .chev { transform: rotate(45deg); }
.faq-a { max-height: 0; overflow: hidden; transition: max-height .3s ease; padding: 0 24px; color: var(--muted); }
.faq-item.open .faq-a { max-height: 320px; padding-bottom: 24px; }

/* Cookie banner */
.cookie {
  position: fixed; left: 24px; right: 24px; bottom: 24px; z-index: 100;
  background: white; border: 1px solid var(--border);
  border-radius: 20px; padding: 24px;
  box-shadow: 0 30px 80px -20px rgba(0,0,0,.25);
  display: flex; gap: 24px; align-items: center;
  max-width: 920px; margin: 0 auto;
}
.cookie p { font-size: 14px; color: var(--muted); flex: 1; }
.cookie p strong { color: var(--dark); display: block; margin-bottom: 4px; font-size: 15px; }
.cookie-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.cookie-actions button { padding: 10px 18px; font-size: 14px; border-radius: 10px; font-weight: 700; }
.cookie-accept { background: var(--dark); color: white; }
.cookie-reject { background: var(--bg-soft); color: var(--dark); }
.cookie-manage { background: transparent; color: var(--primary); }
.cookie.hidden { display: none; }
@media (max-width: 720px) { .cookie { flex-direction: column; align-items: stretch; } }

/* Modal */
.modal-backdrop { position: fixed; inset: 0; background: rgba(15,16,24,.5); z-index: 200; display: none; align-items: center; justify-content: center; padding: 24px; }
.modal-backdrop.open { display: flex; }
.modal { background: white; border-radius: 20px; padding: 32px; max-width: 520px; width: 100%; box-shadow: 0 30px 80px rgba(0,0,0,.3); }
.modal h3 { margin-bottom: 8px; }
.modal > p { color: var(--muted); margin-bottom: 20px; font-size: 14px; }
.cookie-cat { display: flex; justify-content: space-between; align-items: flex-start; padding: 16px; border-radius: 12px; background: var(--bg-soft); margin-bottom: 12px; gap: 12px; }
.cookie-cat strong { display: block; margin-bottom: 4px; }
.cookie-cat span { font-size: 13px; color: var(--muted); }
.modal-foot { display: flex; gap: 12px; margin-top: 16px; }
.modal-foot .btn { flex: 1; }

/* Toggle switch */
.switch { position: relative; width: 44px; height: 24px; flex-shrink: 0; }
.switch input { opacity: 0; width: 0; height: 0; }
.switch-slider { position: absolute; inset: 0; background: #D1D5DB; border-radius: 999px; cursor: pointer; transition: .2s; }
.switch-slider::before { content: ""; position: absolute; left: 3px; top: 3px; width: 18px; height: 18px; background: white; border-radius: 50%; transition: .2s; }
.switch input:checked + .switch-slider { background: var(--primary); }
.switch input:checked + .switch-slider::before { transform: translateX(20px); }
.switch input:disabled + .switch-slider { opacity: .5; cursor: not-allowed; }

/* Auth */
.auth-shell { min-height: 100vh; display: grid; grid-template-columns: 1fr; }
.auth-shell.split { grid-template-columns: 1fr 1fr; }
@media (max-width: 900px) { .auth-shell.split { grid-template-columns: 1fr; } }
.auth-main { padding: 60px 32px; display: flex; flex-direction: column; justify-content: center; align-items: center; }
.auth-card { width: 100%; max-width: 420px; }
.auth-card h1 { font-size: 32px; margin-bottom: 24px; text-align: center; }
.auth-card .sub { text-align: center; color: var(--muted); margin-bottom: 28px; }
.social-btns { display: flex; flex-direction: column; gap: 10px; margin-bottom: 20px; }
.social-btn { width: 100%; padding: 12px 16px; border: 1px solid var(--border); border-radius: 12px; background: white; font-weight: 600; display: flex; align-items: center; gap: 12px; transition: all .2s; }
.social-btn:hover { border-color: var(--primary); background: var(--bg-tint); }
.social-btn .ico { width: 22px; height: 22px; display: grid; place-items: center; font-weight: 800; }
.divider { display: flex; align-items: center; gap: 12px; color: var(--muted); font-size: 13px; margin: 16px 0; }
.divider::before, .divider::after { content: ""; flex: 1; height: 1px; background: var(--border); }
.input-field { width: 100%; padding: 14px 16px; border: 1px solid var(--border); border-radius: 12px; font-size: 15px; font-family: inherit; transition: all .2s; }
.input-field:focus { outline: none; border-color: var(--primary); box-shadow: 0 0 0 4px rgba(109,91,255,.1); }
.auth-form { display: flex; flex-direction: column; gap: 12px; }
.auth-form button[type="submit"] { width: 100%; padding: 14px; background: var(--dark); color: white; border-radius: 12px; font-weight: 700; }
.auth-foot { font-size: 13px; color: var(--muted); margin-top: 20px; line-height: 1.5; text-align: center; }
.auth-link { color: var(--primary); font-weight: 600; }
.testimonial-side { background: var(--gradient); padding: 60px; color: white; display: flex; flex-direction: column; justify-content: center; }
.testimonial-side blockquote { font-size: 26px; font-weight: 600; line-height: 1.4; max-width: 480px; margin-bottom: 28px; }
.testimonial-side .author-block { display: flex; align-items: center; gap: 14px; }
.testimonial-side .author-block .avatar { width: 56px; height: 56px; border-radius: 50%; background: white; color: var(--primary); display: grid; place-items: center; font-weight: 800; font-size: 20px; }
.testimonial-side .author-block .name { font-weight: 700; }
.testimonial-side .author-block .role { opacity: .85; font-size: 14px; }

/* Integrations */
.integ-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 16px; }
@media (max-width: 1080px) { .integ-grid { grid-template-columns: repeat(3, 1fr); } }
.integ-cell { padding: 24px; aspect-ratio: 1; background: white; border: 1px solid var(--border); border-radius: 16px; display: grid; place-items: center; transition: all .25s; }
.integ-cell:hover { border-color: var(--primary); transform: translateY(-3px); }
.integ-cell .label { text-align: center; }
.integ-cell .ico-lg { width: 40px; height: 40px; border-radius: 8px; background: var(--gradient-soft); margin: 0 auto 8px; display: grid; place-items: center; font-weight: 800; color: var(--primary); }
.integ-cell .name { font-size: 13px; font-weight: 600; color: var(--text); }

/* Misc */
.callout {
  background: var(--gradient-soft); border: 1px solid #E8E2FF;
  border-radius: 20px; padding: 28px; display: flex; gap: 20px; align-items: center;
}
.callout .badge { background: var(--accent); color: white; padding: 4px 12px; border-radius: 999px; font-size: 12px; font-weight: 700; align-self: flex-start; }

.checks-list { list-style: none; display: flex; flex-direction: column; gap: 14px; }
.checks-list li { display: flex; gap: 12px; align-items: flex-start; }
.checks-list li::before { content: "✓"; flex-shrink: 0; width: 24px; height: 24px; border-radius: 50%; background: var(--gradient); color: white; display: grid; place-items: center; font-weight: 800; font-size: 13px; }

.blog-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
@media (max-width: 900px) { .blog-grid { grid-template-columns: 1fr; } }
.blog-card { padding: 0; border-radius: 20px; overflow: hidden; background: white; border: 1px solid var(--border); transition: all .25s; }
.blog-card:hover { transform: translateY(-3px); box-shadow: 0 20px 50px -20px rgba(0,0,0,.18); }
.blog-thumb { aspect-ratio: 16/9; background: var(--gradient); position: relative; }
.blog-thumb::after { content: ""; position: absolute; inset: 0; background: radial-gradient(circle at 70% 30%, rgba(255,255,255,.3), transparent 60%); }
.blog-body { padding: 24px; }
.blog-body .tag { font-size: 12px; font-weight: 700; color: var(--primary); text-transform: uppercase; letter-spacing: 0.05em; }
.blog-body h3 { font-size: 20px; margin: 8px 0; }
.blog-body p { color: var(--muted); font-size: 14px; }

/* Carousel */
.carousel { overflow: hidden; }
.carousel-track { display: flex; gap: 24px; transition: transform .4s ease; }
.carousel-card { flex: 0 0 calc(33.333% - 16px); }
@media (max-width: 1080px) { .carousel-card { flex: 0 0 calc(50% - 12px); } }
@media (max-width: 720px) { .carousel-card { flex: 0 0 100%; } }
.carousel-controls { display: flex; gap: 10px; justify-content: center; margin-top: 28px; }
.carousel-controls button { width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--border); background: white; font-size: 18px; transition: all .2s; }
.carousel-controls button:hover { background: var(--dark); color: white; border-color: var(--dark); }

/* ClipCast Design System */
:root {
  --primary: #6D5BFF;
  --primary-dark: #4F3DE8;
  --primary-light: #8B7BFF;
  --indigo: #1868DB;
  --accent: #FF613D;
  --dark: #1A1B23;
  --text: #292A2E;
  --muted: #6B7280;
  --border: #E5E7EB;
  --bg-soft: #F7F6FE;
  --bg-tint: #FAF9FF;
  --gradient: linear-gradient(135deg, #6D5BFF 0%, #9B7BFF 50%, #FF613D 100%);
  --gradient-soft: linear-gradient(135deg, #F4F1FF 0%, #FFF4F0 100%);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--text);
  background: #fff;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

.container { max-width: 1240px; margin: 0 auto; padding: 0 24px; }
.container-narrow { max-width: 1040px; margin: 0 auto; padding: 0 24px; }

/* Typography */
h1, h2, h3, h4 { font-family: 'Plus Jakarta Sans', sans-serif; color: var(--dark); letter-spacing: -0.02em; line-height: 1.15; font-weight: 800; }
h1 { font-size: clamp(2.5rem, 5vw, 4.25rem); }
h2 { font-size: clamp(2rem, 3.5vw, 3rem); }
h3 { font-size: clamp(1.5rem, 2.2vw, 2rem); }
h4 { font-size: 1.25rem; font-weight: 700; }

.eyebrow { display: inline-flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: var(--primary); padding: 6px 14px; background: rgba(109,91,255,0.1); border-radius: 999px; }

/* Nav */
.nav {
  position: sticky; top: 0; z-index: 50;
  background: rgba(255,255,255,0.85);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}
.nav-inner { display: flex; align-items: center; justify-content: space-between; height: 72px; }
.logo { display: flex; align-items: center; gap: 8px; font-weight: 800; font-size: 22px; color: var(--dark); }
.logo-mark {
  width: 32px; height: 32px; border-radius: 8px;
  background: var(--gradient);
  display: grid; place-items: center;
  position: relative;
}
.logo-mark::after {
  content: ""; width: 0; height: 0;
  border-left: 8px solid white;
  border-top: 5px solid transparent;
  border-bottom: 5px solid transparent;
  margin-left: 2px;
}
.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links a { font-weight: 600; color: var(--text); font-size: 15px; transition: color .15s; }
.nav-links a:hover { color: var(--primary); }
.nav-cta { display: flex; align-items: center; gap: 12px; }

@media (max-width: 900px) {
  .nav-links { display: none; }
}

/* Buttons */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 12px 22px; border-radius: 12px; font-weight: 700; font-size: 15px; transition: all .2s ease; white-space: nowrap; }
.btn-primary { background: var(--dark); color: white; }
.btn-primary:hover { background: var(--primary); transform: translateY(-1px); box-shadow: 0 12px 28px -8px rgba(109,91,255,.45); }
.btn-accent { background: var(--gradient); color: white; }
.btn-accent:hover { transform: translateY(-1px); box-shadow: 0 14px 32px -10px rgba(109,91,255,.55); }
.btn-ghost { color: var(--dark); }
.btn-ghost:hover { color: var(--primary); }
.btn-outline { background: white; color: var(--dark); border: 2px solid var(--dark); }
.btn-outline:hover { background: var(--dark); color: white; }
.btn-lg { padding: 16px 28px; font-size: 16px; border-radius: 14px; }

/* Sections */
section { padding: 80px 0; }
.section-tight { padding: 56px 0; }
.section-soft { background: var(--bg-soft); }
.section-tint { background: var(--bg-tint); }
.section-dark { background: var(--dark); color: white; }
.section-dark h1, .section-dark h2, .section-dark h3, .section-dark h4 { color: white; }

/* Hero */
.hero { padding: 80px 0 100px; position: relative; overflow: hidden; }
.hero-bg {
  position: absolute; inset: 0; z-index: -1;
  background:
    radial-gradient(ellipse 80% 50% at 20% 20%, rgba(109,91,255,.18), transparent 60%),
    radial-gradient(ellipse 60% 50% at 90% 80%, rgba(255,97,61,.14), transparent 60%),
    linear-gradient(180deg, #FBFAFF 0%, #FFFFFF 100%);
}
.hero-grid { display: grid; grid-template-columns: 1.1fr 1fr; gap: 60px; align-items: center; }
.hero h1 span.grad { background: var(--gradient); -webkit-background-clip: text; background-clip: text; color: transparent; }
.hero p { font-size: 19px; color: var(--muted); margin: 24px 0 32px; max-width: 540px; }
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }
.hero-meta { margin-top: 24px; font-size: 14px; color: var(--muted); display: flex; gap: 18px; }
.hero-meta span::before { content: "✓"; color: var(--primary); margin-right: 6px; font-weight: 800; }

@media (max-width: 900px) {
  .hero-grid { grid-template-columns: 1fr; }
}

/* Mock video card */
.mock-video {
  position: relative; aspect-ratio: 16/10;
  background: var(--gradient);
  border-radius: 24px;
  padding: 14px;
  box-shadow: 0 30px 80px -20px rgba(109,91,255,.5);
  transform: rotate(-1.5deg);
  transition: transform .4s ease;
}
.mock-video:hover { transform: rotate(0); }
.mock-video-inner {
  background: linear-gradient(135deg, #2d2740 0%, #1a1530 100%);
  border-radius: 16px; height: 100%;
  position: relative; overflow: hidden;
  display: grid; place-items: center;
}
.mock-video-inner::before {
  content: ""; position: absolute; inset: 0;
  background:
    radial-gradient(circle at 70% 30%, rgba(255,97,61,.4), transparent 50%),
    radial-gradient(circle at 30% 70%, rgba(109,91,255,.4), transparent 50%);
}
.mock-play {
  position: relative; z-index: 2;
  width: 84px; height: 84px; border-radius: 50%;
  background: white; display: grid; place-items: center;
  box-shadow: 0 20px 50px rgba(0,0,0,.3);
}
.mock-play::after {
  content: ""; width: 0; height: 0;
  border-left: 24px solid var(--primary);
  border-top: 14px solid transparent;
  border-bottom: 14px solid transparent;
  margin-left: 6px;
}
.mock-cam {
  position: absolute; bottom: 28px; left: 28px; z-index: 3;
  width: 90px; height: 90px; border-radius: 50%;
  background: linear-gradient(135deg, #FFB199, #FF613D);
  border: 4px solid white;
  box-shadow: 0 10px 30px rgba(0,0,0,.25);
}
.mock-toolbar {
  position: absolute; bottom: 28px; right: 28px; z-index: 3;
  display: flex; gap: 8px;
  background: rgba(255,255,255,.95); padding: 8px; border-radius: 999px;
  backdrop-filter: blur(8px);
}
.mock-toolbar i { width: 32px; height: 32px; border-radius: 50%; background: var(--bg-soft); display: grid; place-items: center; font-style: normal; }

/* Logo bar */
.logo-bar { padding: 60px 0; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
.logo-bar p { text-align: center; color: var(--muted); margin-bottom: 28px; font-weight: 600; font-size: 14px; letter-spacing: 0.05em; text-transform: uppercase; }
.logo-row { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 28px; }
.logo-row .brand { font-weight: 800; font-size: 22px; color: var(--muted); opacity: .65; letter-spacing: -0.02em; transition: opacity .2s; }
.logo-row .brand:hover { opacity: 1; }

/* Cards */
.card {
  background: white; border: 1px solid var(--border);
  border-radius: 20px; padding: 32px;
  transition: transform .25s ease, box-shadow .25s ease, border-color .25s;
}
.card:hover { transform: translateY(-3px); box-shadow: 0 20px 50px -20px rgba(26,27,35,.18); border-color: rgba(109,91,255,.3); }
.card-icon {
  width: 56px; height: 56px; border-radius: 14px;
  background: var(--gradient-soft);
  display: grid; place-items: center;
  font-size: 24px; margin-bottom: 20px;
}
.card h3 { font-size: 22px; margin-bottom: 8px; }
.card p { color: var(--muted); }

/* Section header */
.section-head { text-align: center; max-width: 720px; margin: 0 auto 56px; }
.section-head .eyebrow { margin-bottom: 16px; }
.section-head p { color: var(--muted); margin-top: 16px; font-size: 18px; }

/* Feature row */
.feature-row { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
.feature-row.flip { direction: rtl; }
.feature-row.flip > * { direction: ltr; }
.feature-row img, .feature-row .feature-visual { width: 100%; border-radius: 24px; }
.feature-row h2 { margin-bottom: 16px; }
.feature-row p { color: var(--muted); font-size: 17px; margin-bottom: 24px; }
@media (max-width: 900px) {
  .feature-row { grid-template-columns: 1fr; gap: 36px; }
  .feature-row.flip { direction: ltr; }
}

.feature-visual {
  aspect-ratio: 4/3; background: var(--gradient-soft);
  border: 1px solid var(--border);
  position: relative; overflow: hidden;
  display: grid; place-items: center;
}
.fv-tag {
  position: absolute; top: 24px; left: 24px;
  background: white; padding: 8px 16px; border-radius: 999px;
  font-size: 12px; font-weight: 700; color: var(--primary);
  box-shadow: 0 6px 20px rgba(0,0,0,.08);
}
.fv-circle {
  width: 60%; aspect-ratio: 1; border-radius: 50%;
  background: var(--gradient); opacity: .7;
  position: relative;
}
.fv-window {
  width: 80%; aspect-ratio: 16/9; background: white;
  border-radius: 16px; box-shadow: 0 30px 60px -20px rgba(0,0,0,.18);
  overflow: hidden;
}
.fv-window-bar { display: flex; gap: 6px; padding: 12px; border-bottom: 1px solid var(--border); }
.fv-window-bar i { width: 10px; height: 10px; border-radius: 50%; background: #FF6058; }
.fv-window-bar i:nth-child(2) { background: #FFBD2E; }
.fv-window-bar i:nth-child(3) { background: #28CA41; }
.fv-window-body { padding: 18px; display: grid; gap: 10px; }
.fv-bar { height: 10px; border-radius: 5px; background: var(--bg-soft); }
.fv-bar.lg { background: var(--gradient); width: 70%; }
.fv-bar.md { width: 90%; }
.fv-bar.sm { width: 50%; }

/* Grid */
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
@media (max-width: 900px) {
  .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .grid-2 { grid-template-columns: 1fr; }
}
@media (max-width: 1080px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
}

/* Use case card */
.usecase {
  padding: 28px; border-radius: 20px;
  background: white; border: 1px solid var(--border);
  display: flex; flex-direction: column; gap: 14px;
  transition: all .25s;
}
.usecase:hover { border-color: var(--primary); transform: translateY(-3px); }
.usecase .pill { font-size: 13px; font-weight: 700; padding: 4px 10px; border-radius: 999px; align-self: flex-start; }
.uc-sales .pill { background: #FFE6DD; color: #C73E1D; }
.uc-eng .pill { background: #DBEAFE; color: #1E40AF; }
.uc-support .pill { background: #DCFCE7; color: #15803D; }
.uc-design .pill { background: #FAE8FF; color: #86198F; }
.usecase h3 { font-size: 22px; }
.usecase p { color: var(--muted); }

/* Features list grid */
.feat-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.feat-cell { padding: 24px; border-radius: 16px; background: white; border: 1px solid var(--border); display: flex; flex-direction: column; gap: 10px; }
.feat-cell .ico {
  width: 40px; height: 40px; border-radius: 10px;
  background: var(--gradient-soft);
  display: grid; place-items: center;
}
.feat-cell h4 { font-size: 16px; }
@media (max-width: 1080px) { .feat-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .feat-grid { grid-template-columns: 1fr; } }

/* Stats */
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; text-align: center; }
.stat .num {
  font-size: clamp(3rem, 6vw, 5rem); font-weight: 800;
  background: var(--gradient); -webkit-background-clip: text; background-clip: text; color: transparent;
  letter-spacing: -0.04em; line-height: 1;
}
.stat p { color: var(--muted); margin-top: 8px; font-size: 17px; }
@media (max-width: 900px) { .stats-grid { grid-template-columns: 1fr; } }

/* Testimonials */
.test-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
@media (max-width: 1080px) { .test-grid { grid-template-columns: 1fr; } }
.testimonial {
  padding: 32px; border-radius: 20px;
  background: white; border: 1px solid var(--border);
  display: flex; flex-direction: column; gap: 20px;
}
.testimonial p.quote { font-size: 17px; line-height: 1.6; color: var(--text); }
.testimonial .author { display: flex; align-items: center; gap: 12px; margin-top: auto; }
.testimonial .avatar {
  width: 48px; height: 48px; border-radius: 50%;
  background: var(--gradient); color: white; display: grid; place-items: center;
  font-weight: 700;
}
.testimonial .name { font-weight: 700; color: var(--dark); }
.testimonial .role { font-size: 13px; color: var(--muted); }

/* CTA banner */
.cta-banner {
  border-radius: 32px; padding: 80px 48px;
  background: var(--gradient); color: white;
  text-align: center; position: relative; overflow: hidden;
}
.cta-banner::before {
  content: ""; position: absolute; inset: 0;
  background: radial-gradient(circle at 80% 20%, rgba(255,255,255,.2), transparent 50%);
}
.cta-banner h2 { color: white; margin-bottom: 16px; position: relative; }
.cta-banner p { font-size: 18px; opacity: .9; margin-bottom: 32px; position: relative; }
.cta-banner .btn { background: white; color: var(--dark); position: relative; }
.cta-banner .btn:hover { background: var(--dark); color: white; }

/* Footer */
.footer { background: #0F1018; color: #C9C9D6; padding: 80px 0 40px; }
.footer h4 { font-size: 14px; text-transform: uppercase; letter-spacing: 0.08em; color: white; margin-bottom: 18px; font-weight: 700; }
.footer-grid { display: grid; grid-template-columns: 1.5fr repeat(5, 1fr); gap: 40px; padding-bottom: 48px; border-bottom: 1px solid rgba(255,255,255,.1); }
.footer-grid ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-grid a { color: #9696A6; font-size: 14px; transition: color .15s; }
.footer-grid a:hover { color: white; }
.footer .logo { color: white; margin-bottom: 16px; }
.footer-bottom { padding-top: 32px; display: flex; justify-content: space-between; flex-wrap: wrap; gap: 16px; font-size: 13px; color: #6E6E80; }
@media (max-width: 1080px) { .footer-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .footer-grid { grid-template-columns: 1fr; } }

/* Pricing */
.billing-toggle { display: inline-flex; align-items: center; gap: 12px; background: var(--bg-soft); padding: 6px; border-radius: 999px; }
.billing-toggle button {
  padding: 10px 22px; border-radius: 999px;
  font-weight: 700; color: var(--muted); font-size: 14px;
  transition: all .2s;
}
.billing-toggle button.active { background: white; color: var(--dark); box-shadow: 0 2px 10px rgba(0,0,0,.06); }
.save-badge { display: inline-flex; padding: 4px 10px; background: #FFE6DD; color: var(--accent); border-radius: 999px; font-size: 12px; font-weight: 700; margin-left: 4px; }

.plan-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; align-items: stretch; }
@media (max-width: 1080px) { .plan-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .plan-grid { grid-template-columns: 1fr; } }
.plan {
  padding: 32px 24px; border-radius: 20px;
  background: white; border: 1px solid var(--border);
  display: flex; flex-direction: column; gap: 20px;
  position: relative;
}
.plan.popular { border-color: var(--primary); border-width: 2px; box-shadow: 0 30px 60px -20px rgba(109,91,255,.3); }
.plan-tag { position: absolute; top: -14px; left: 50%; transform: translateX(-50%); background: var(--gradient); color: white; padding: 6px 14px; border-radius: 999px; font-size: 12px; font-weight: 700; letter-spacing: 0.05em; }
.plan h3 { font-size: 20px; }
.plan .price { display: flex; align-items: baseline; gap: 4px; }
.plan .price .amount { font-size: 44px; font-weight: 800; color: var(--dark); letter-spacing: -0.03em; }
.plan .price .unit { color: var(--muted); font-size: 14px; font-weight: 600; }
.plan .desc { color: var(--muted); font-size: 14px; min-height: 42px; }
.plan ul { list-style: none; display: flex; flex-direction: column; gap: 12px; }
.plan ul li { font-size: 14px; color: var(--text); display: flex; gap: 10px; }
.plan ul li::before { content: "✓"; color: var(--primary); font-weight: 800; flex-shrink: 0; }
.plan .btn { width: 100%; }

/* Slider */
.slider-card {
  background: white; border: 1px solid var(--border);
  border-radius: 20px; padding: 28px;
  display: flex; flex-direction: column; gap: 16px; max-width: 640px; margin: 0 auto;
}
.slider-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; }
.slider-row label { font-weight: 700; }
.slider-value { font-weight: 800; color: var(--primary); font-size: 18px; }
input[type="range"] {
  -webkit-appearance: none; appearance: none;
  width: 100%; height: 6px; border-radius: 999px;
  background: linear-gradient(90deg, var(--primary) 0%, var(--primary) var(--val,30%), #E5E7EB var(--val,30%), #E5E7EB 100%);
  outline: none;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none; appearance: none;
  width: 24px; height: 24px; border-radius: 50%;
  background: white; border: 3px solid var(--primary);
  cursor: pointer; box-shadow: 0 4px 10px rgba(109,91,255,.3);
}
input[type="range"]::-moz-range-thumb {
  width: 24px; height: 24px; border-radius: 50%;
  background: white; border: 3px solid var(--primary); cursor: pointer;
}
.slider-result { font-size: 14px; color: var(--muted); padding-top: 10px; border-top: 1px solid var(--border); }
.slider-result strong { color: var(--dark); }

/* Comparison Table */
.comp-table-wrapper { overflow-x: auto; border-radius: 20px; border: 1px solid var(--border); background: white; }
.comp-table { width: 100%; border-collapse: collapse; min-width: 720px; }
.comp-table th, .comp-table td { padding: 16px 18px; text-align: left; border-bottom: 1px solid var(--border); font-size: 14px; }
.comp-table th { background: var(--bg-soft); font-weight: 700; color: var(--dark); font-size: 13px; text-transform: uppercase; letter-spacing: 0.05em; }
.comp-table td:first-child { font-weight: 600; color: var(--dark); }
.comp-table .check { color: var(--primary); font-weight: 800; }
.comp-table .dash { color: #C9C9D0; }
.comp-table tr.section-row td { background: var(--bg-tint); font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; font-size: 12px; color: var(--primary); }
.comp-collapse { max-height: 480px; overflow: hidden; transition: max-height .4s ease; position: relative; }
.comp-collapse.expanded { max-height: 4000px; }
.comp-fade { position: absolute; bottom: 0; left: 0; right: 0; height: 100px; background: linear-gradient(to top, white, transparent); pointer-events: none; transition: opacity .3s; }
.comp-collapse.expanded .comp-fade { opacity: 0; }

/* FAQ */
.faq-list { display: flex; flex-direction: column; gap: 12px; max-width: 820px; margin: 0 auto; }
.faq-item { background: white; border: 1px solid var(--border); border-radius: 14px; overflow: hidden; transition: border-color .2s; }
.faq-item.open { border-color: var(--primary); }
.faq-q { width: 100%; padding: 22px 24px; display: flex; justify-content: space-between; align-items: center; gap: 16px; font-weight: 700; font-size: 17px; text-align: left; color: var(--dark); }
.faq-q .chev { transition: transform .25s; flex-shrink: 0; color: var(--primary); font-size: 22px; line-height: 1; }
.faq-item.open .chev { transform: rotate(45deg); }
.faq-a { max-height: 0; overflow: hidden; transition: max-height .3s ease; padding: 0 24px; color: var(--muted); }
.faq-item.open .faq-a { max-height: 320px; padding-bottom: 24px; }

/* Cookie banner */
.cookie {
  position: fixed; left: 24px; right: 24px; bottom: 24px; z-index: 100;
  background: white; border: 1px solid var(--border);
  border-radius: 20px; padding: 24px;
  box-shadow: 0 30px 80px -20px rgba(0,0,0,.25);
  display: flex; gap: 24px; align-items: center;
  max-width: 920px; margin: 0 auto;
}
.cookie p { font-size: 14px; color: var(--muted); flex: 1; }
.cookie p strong { color: var(--dark); display: block; margin-bottom: 4px; font-size: 15px; }
.cookie-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.cookie-actions button { padding: 10px 18px; font-size: 14px; border-radius: 10px; font-weight: 700; }
.cookie-accept { background: var(--dark); color: white; }
.cookie-reject { background: var(--bg-soft); color: var(--dark); }
.cookie-manage { background: transparent; color: var(--primary); }
.cookie.hidden { display: none; }
@media (max-width: 720px) { .cookie { flex-direction: column; align-items: stretch; } }

/* Modal */
.modal-backdrop { position: fixed; inset: 0; background: rgba(15,16,24,.5); z-index: 200; display: none; align-items: center; justify-content: center; padding: 24px; }
.modal-backdrop.open { display: flex; }
.modal { background: white; border-radius: 20px; padding: 32px; max-width: 520px; width: 100%; box-shadow: 0 30px 80px rgba(0,0,0,.3); }
.modal h3 { margin-bottom: 8px; }
.modal > p { color: var(--muted); margin-bottom: 20px; font-size: 14px; }
.cookie-cat { display: flex; justify-content: space-between; align-items: flex-start; padding: 16px; border-radius: 12px; background: var(--bg-soft); margin-bottom: 12px; gap: 12px; }
.cookie-cat strong { display: block; margin-bottom: 4px; }
.cookie-cat span { font-size: 13px; color: var(--muted); }
.modal-foot { display: flex; gap: 12px; margin-top: 16px; }
.modal-foot .btn { flex: 1; }

/* Toggle switch */
.switch { position: relative; width: 44px; height: 24px; flex-shrink: 0; }
.switch input { opacity: 0; width: 0; height: 0; }
.switch-slider { position: absolute; inset: 0; background: #D1D5DB; border-radius: 999px; cursor: pointer; transition: .2s; }
.switch-slider::before { content: ""; position: absolute; left: 3px; top: 3px; width: 18px; height: 18px; background: white; border-radius: 50%; transition: .2s; }
.switch input:checked + .switch-slider { background: var(--primary); }
.switch input:checked + .switch-slider::before { transform: translateX(20px); }
.switch input:disabled + .switch-slider { opacity: .5; cursor: not-allowed; }

/* Auth */
.auth-shell { min-height: 100vh; display: grid; grid-template-columns: 1fr; }
.auth-shell.split { grid-template-columns: 1fr 1fr; }
@media (max-width: 900px) { .auth-shell.split { grid-template-columns: 1fr; } }
.auth-main { padding: 60px 32px; display: flex; flex-direction: column; justify-content: center; align-items: center; }
.auth-card { width: 100%; max-width: 420px; }
.auth-card h1 { font-size: 32px; margin-bottom: 24px; text-align: center; }
.auth-card .sub { text-align: center; color: var(--muted); margin-bottom: 28px; }
.social-btns { display: flex; flex-direction: column; gap: 10px; margin-bottom: 20px; }
.social-btn { width: 100%; padding: 12px 16px; border: 1px solid var(--border); border-radius: 12px; background: white; font-weight: 600; display: flex; align-items: center; gap: 12px; transition: all .2s; }
.social-btn:hover { border-color: var(--primary); background: var(--bg-tint); }
.social-btn .ico { width: 22px; height: 22px; display: grid; place-items: center; font-weight: 800; }
.divider { display: flex; align-items: center; gap: 12px; color: var(--muted); font-size: 13px; margin: 16px 0; }
.divider::before, .divider::after { content: ""; flex: 1; height: 1px; background: var(--border); }
.input-field { width: 100%; padding: 14px 16px; border: 1px solid var(--border); border-radius: 12px; font-size: 15px; font-family: inherit; transition: all .2s; }
.input-field:focus { outline: none; border-color: var(--primary); box-shadow: 0 0 0 4px rgba(109,91,255,.1); }
.auth-form { display: flex; flex-direction: column; gap: 12px; }
.auth-form button[type="submit"] { width: 100%; padding: 14px; background: var(--dark); color: white; border-radius: 12px; font-weight: 700; }
.auth-foot { font-size: 13px; color: var(--muted); margin-top: 20px; line-height: 1.5; text-align: center; }
.auth-link { color: var(--primary); font-weight: 600; }
.testimonial-side { background: var(--gradient); padding: 60px; color: white; display: flex; flex-direction: column; justify-content: center; }
.testimonial-side blockquote { font-size: 26px; font-weight: 600; line-height: 1.4; max-width: 480px; margin-bottom: 28px; }
.testimonial-side .author-block { display: flex; align-items: center; gap: 14px; }
.testimonial-side .author-block .avatar { width: 56px; height: 56px; border-radius: 50%; background: white; color: var(--primary); display: grid; place-items: center; font-weight: 800; font-size: 20px; }
.testimonial-side .author-block .name { font-weight: 700; }
.testimonial-side .author-block .role { opacity: .85; font-size: 14px; }

/* Integrations */
.integ-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 16px; }
@media (max-width: 1080px) { .integ-grid { grid-template-columns: repeat(3, 1fr); } }
.integ-cell { padding: 24px; aspect-ratio: 1; background: white; border: 1px solid var(--border); border-radius: 16px; display: grid; place-items: center; transition: all .25s; }
.integ-cell:hover { border-color: var(--primary); transform: translateY(-3px); }
.integ-cell .label { text-align: center; }
.integ-cell .ico-lg { width: 40px; height: 40px; border-radius: 8px; background: var(--gradient-soft); margin: 0 auto 8px; display: grid; place-items: center; font-weight: 800; color: var(--primary); }
.integ-cell .name { font-size: 13px; font-weight: 600; color: var(--text); }

/* Misc */
.callout {
  background: var(--gradient-soft); border: 1px solid #E8E2FF;
  border-radius: 20px; padding: 28px; display: flex; gap: 20px; align-items: center;
}
.callout .badge { background: var(--accent); color: white; padding: 4px 12px; border-radius: 999px; font-size: 12px; font-weight: 700; align-self: flex-start; }

.checks-list { list-style: none; display: flex; flex-direction: column; gap: 14px; }
.checks-list li { display: flex; gap: 12px; align-items: flex-start; }
.checks-list li::before { content: "✓"; flex-shrink: 0; width: 24px; height: 24px; border-radius: 50%; background: var(--gradient); color: white; display: grid; place-items: center; font-weight: 800; font-size: 13px; }

.blog-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
@media (max-width: 900px) { .blog-grid { grid-template-columns: 1fr; } }
.blog-card { padding: 0; border-radius: 20px; overflow: hidden; background: white; border: 1px solid var(--border); transition: all .25s; }
.blog-card:hover { transform: translateY(-3px); box-shadow: 0 20px 50px -20px rgba(0,0,0,.18); }
.blog-thumb { aspect-ratio: 16/9; background: var(--gradient); position: relative; }
.blog-thumb::after { content: ""; position: absolute; inset: 0; background: radial-gradient(circle at 70% 30%, rgba(255,255,255,.3), transparent 60%); }
.blog-body { padding: 24px; }
.blog-body .tag { font-size: 12px; font-weight: 700; color: var(--primary); text-transform: uppercase; letter-spacing: 0.05em; }
.blog-body h3 { font-size: 20px; margin: 8px 0; }
.blog-body p { color: var(--muted); font-size: 14px; }

/* Carousel */
.carousel { overflow: hidden; }
.carousel-track { display: flex; gap: 24px; transition: transform .4s ease; }
.carousel-card { flex: 0 0 calc(33.333% - 16px); }
@media (max-width: 1080px) { .carousel-card { flex: 0 0 calc(50% - 12px); } }
@media (max-width: 720px) { .carousel-card { flex: 0 0 100%; } }
.carousel-controls { display: flex; gap: 10px; justify-content: center; margin-top: 28px; }
.carousel-controls button { width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--border); background: white; font-size: 18px; transition: all .2s; }
.carousel-controls button:hover { background: var(--dark); color: white; border-color: var(--dark); }

raw_arguments.content:
/* ClipCast Design System */
:root {
  --primary: #6D5BFF;
  --primary-dark: #4F3DE8;
  --primary-light: #8B7BFF;
  --indigo: #1868DB;
  --accent: #FF613D;
  --dark: #1A1B23;
  --text: #292A2E;
  --muted: #6B7280;
  --border: #E5E7EB;
  --bg-soft: #F7F6FE;
  --bg-tint: #FAF9FF;
  --gradient: linear-gradient(135deg, #6D5BFF 0%, #9B7BFF 50%, #FF613D 100%);
  --gradient-soft: linear-gradient(135deg, #F4F1FF 0%, #FFF4F0 100%);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--text);
  background: #fff;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

.container { max-width: 1240px; margin: 0 auto; padding: 0 24px; }
.container-narrow { max-width: 1040px; margin: 0 auto; padding: 0 24px; }

/* Typography */
h1, h2, h3, h4 { font-family: 'Plus Jakarta Sans', sans-serif; color: var(--dark); letter-spacing: -0.02em; line-height: 1.15; font-weight: 800; }
h1 { font-size: clamp(2.5rem, 5vw, 4.25rem); }
h2 { font-size: clamp(2rem, 3.5vw, 3rem); }
h3 { font-size: clamp(1.5rem, 2.2vw, 2rem); }
h4 { font-size: 1.25rem; font-weight: 700; }

.eyebrow { display: inline-flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: var(--primary); padding: 6px 14px; background: rgba(109,91,255,0.1); border-radius: 999px; }

/* Nav */
.nav {
  position: sticky; top: 0; z-index: 50;
  background: rgba(255,255,255,0.85);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}
.nav-inner { display: flex; align-items: center; justify-content: space-between; height: 72px; }
.logo { display: flex; align-items: center; gap: 8px; font-weight: 800; font-size: 22px; color: var(--dark); }
.logo-mark {
  width: 32px; height: 32px; border-radius: 8px;
  background: var(--gradient);
  display: grid; place-items: center;
  position: relative;
}
.logo-mark::after {
  content: ""; width: 0; height: 0;
  border-left: 8px solid white;
  border-top: 5px solid transparent;
  border-bottom: 5px solid transparent;
  margin-left: 2px;
}
.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links a { font-weight: 600; color: var(--text); font-size: 15px; transition: color .15s; }
.nav-links a:hover { color: var(--primary); }
.nav-cta { display: flex; align-items: center; gap: 12px; }

@media (max-width: 900px) {
  .nav-links { display: none; }
}

/* Buttons */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 12px 22px; border-radius: 12px; font-weight: 700; font-size: 15px; transition: all .2s ease; white-space: nowrap; }
.btn-primary { background: var(--dark); color: white; }
.btn-primary:hover { background: var(--primary); transform: translateY(-1px); box-shadow: 0 12px 28px -8px rgba(109,91,255,.45); }
.btn-accent { background: var(--gradient); color: white; }
.btn-accent:hover { transform: translateY(-1px); box-shadow: 0 14px 32px -10px rgba(109,91,255,.55); }
.btn-ghost { color: var(--dark); }
.btn-ghost:hover { color: var(--primary); }
.btn-outline { background: white; color: var(--dark); border: 2px solid var(--dark); }
.btn-outline:hover { background: var(--dark); color: white; }
.btn-lg { padding: 16px 28px; font-size: 16px; border-radius: 14px; }

/* Sections */
section { padding: 80px 0; }
.section-tight { padding: 56px 0; }
.section-soft { background: var(--bg-soft); }
.section-tint { background: var(--bg-tint); }
.section-dark { background: var(--dark); color: white; }
.section-dark h1, .section-dark h2, .section-dark h3, .section-dark h4 { color: white; }

/* Hero */
.hero { padding: 80px 0 100px; position: relative; overflow: hidden; }
.hero-bg {
  position: absolute; inset: 0; z-index: -1;
  background:
    radial-gradient(ellipse 80% 50% at 20% 20%, rgba(109,91,255,.18), transparent 60%),
    radial-gradient(ellipse 60% 50% at 90% 80%, rgba(255,97,61,.14), transparent 60%),
    linear-gradient(180deg, #FBFAFF 0%, #FFFFFF 100%);
}
.hero-grid { display: grid; grid-template-columns: 1.1fr 1fr; gap: 60px; align-items: center; }
.hero h1 span.grad { background: var(--gradient); -webkit-background-clip: text; background-clip: text; color: transparent; }
.hero p { font-size: 19px; color: var(--muted); margin: 24px 0 32px; max-width: 540px; }
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }
.hero-meta { margin-top: 24px; font-size: 14px; color: var(--muted); display: flex; gap: 18px; }
.hero-meta span::before { content: "✓"; color: var(--primary); margin-right: 6px; font-weight: 800; }

@media (max-width: 900px) {
  .hero-grid { grid-template-columns: 1fr; }
}

/* Mock video card */
.mock-video {
  position: relative; aspect-ratio: 16/10;
  background: var(--gradient);
  border-radius: 24px;
  padding: 14px;
  box-shadow: 0 30px 80px -20px rgba(109,91,255,.5);
  transform: rotate(-1.5deg);
  transition: transform .4s ease;
}
.mock-video:hover { transform: rotate(0); }
.mock-video-inner {
  background: linear-gradient(135deg, #2d2740 0%, #1a1530 100%);
  border-radius: 16px; height: 100%;
  position: relative; overflow: hidden;
  display: grid; place-items: center;
}
.mock-video-inner::before {
  content: ""; position: absolute; inset: 0;
  background:
    radial-gradient(circle at 70% 30%, rgba(255,97,61,.4), transparent 50%),
    radial-gradient(circle at 30% 70%, rgba(109,91,255,.4), transparent 50%);
}
.mock-play {
  position: relative; z-index: 2;
  width: 84px; height: 84px; border-radius: 50%;
  background: white; display: grid; place-items: center;
  box-shadow: 0 20px 50px rgba(0,0,0,.3);
}
.mock-play::after {
  content: ""; width: 0; height: 0;
  border-left: 24px solid var(--primary);
  border-top: 14px solid transparent;
  border-bottom: 14px solid transparent;
  margin-left: 6px;
}
.mock-cam {
  position: absolute; bottom: 28px; left: 28px; z-index: 3;
  width: 90px; height: 90px; border-radius: 50%;
  background: linear-gradient(135deg, #FFB199, #FF613D);
  border: 4px solid white;
  box-shadow: 0 10px 30px rgba(0,0,0,.25);
}
.mock-toolbar {
  position: absolute; bottom: 28px; right: 28px; z-index: 3;
  display: flex; gap: 8px;
  background: rgba(255,255,255,.95); padding: 8px; border-radius: 999px;
  backdrop-filter: blur(8px);
}
.mock-toolbar i { width: 32px; height: 32px; border-radius: 50%; background: var(--bg-soft); display: grid; place-items: center; font-style: normal; }

/* Logo bar */
.logo-bar { padding: 60px 0; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
.logo-bar p { text-align: center; color: var(--muted); margin-bottom: 28px; font-weight: 600; font-size: 14px; letter-spacing: 0.05em; text-transform: uppercase; }
.logo-row { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 28px; }
.logo-row .brand { font-weight: 800; font-size: 22px; color: var(--muted); opacity: .65; letter-spacing: -0.02em; transition: opacity .2s; }
.logo-row .brand:hover { opacity: 1; }

/* Cards */
.card {
  background: white; border: 1px solid var(--border);
  border-radius: 20px; padding: 32px;
  transition: transform .25s ease, box-shadow .25s ease, border-color .25s;
}
.card:hover { transform: translateY(-3px); box-shadow: 0 20px 50px -20px rgba(26,27,35,.18); border-color: rgba(109,91,255,.3); }
.card-icon {
  width: 56px; height: 56px; border-radius: 14px;
  background: var(--gradient-soft);
  display: grid; place-items: center;
  font-size: 24px; margin-bottom: 20px;
}
.card h3 { font-size: 22px; margin-bottom: 8px; }
.card p { color: var(--muted); }

/* Section header */
.section-head { text-align: center; max-width: 720px; margin: 0 auto 56px; }
.section-head .eyebrow { margin-bottom: 16px; }
.section-head p { color: var(--muted); margin-top: 16px; font-size: 18px; }

/* Feature row */
.feature-row { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
.feature-row.flip { direction: rtl; }
.feature-row.flip > * { direction: ltr; }
.feature-row img, .feature-row .feature-visual { width: 100%; border-radius: 24px; }
.feature-row h2 { margin-bottom: 16px; }
.feature-row p { color: var(--muted); font-size: 17px; margin-bottom: 24px; }
@media (max-width: 900px) {
  .feature-row { grid-template-columns: 1fr; gap: 36px; }
  .feature-row.flip { direction: ltr; }
}

.feature-visual {
  aspect-ratio: 4/3; background: var(--gradient-soft);
  border: 1px solid var(--border);
  position: relative; overflow: hidden;
  display: grid; place-items: center;
}
.fv-tag {
  position: absolute; top: 24px; left: 24px;
  background: white; padding: 8px 16px; border-radius: 999px;
  font-size: 12px; font-weight: 700; color: var(--primary);
  box-shadow: 0 6px 20px rgba(0,0,0,.08);
}
.fv-circle {
  width: 60%; aspect-ratio: 1; border-radius: 50%;
  background: var(--gradient); opacity: .7;
  position: relative;
}
.fv-window {
  width: 80%; aspect-ratio: 16/9; background: white;
  border-radius: 16px; box-shadow: 0 30px 60px -20px rgba(0,0,0,.18);
  overflow: hidden;
}
.fv-window-bar { display: flex; gap: 6px; padding: 12px; border-bottom: 1px solid var(--border); }
.fv-window-bar i { width: 10px; height: 10px; border-radius: 50%; background: #FF6058; }
.fv-window-bar i:nth-child(2) { background: #FFBD2E; }
.fv-window-bar i:nth-child(3) { background: #28CA41; }
.fv-window-body { padding: 18px; display: grid; gap: 10px; }
.fv-bar { height: 10px; border-radius: 5px; background: var(--bg-soft); }
.fv-bar.lg { background: var(--gradient); width: 70%; }
.fv-bar.md { width: 90%; }
.fv-bar.sm { width: 50%; }

/* Grid */
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
@media (max-width: 900px) {
  .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .grid-2 { grid-template-columns: 1fr; }
}
@media (max-width: 1080px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
}

/* Use case card */
.usecase {
  padding: 28px; border-radius: 20px;
  background: white; border: 1px solid var(--border);
  display: flex; flex-direction: column; gap: 14px;
  transition: all .25s;
}
.usecase:hover { border-color: var(--primary); transform: translateY(-3px); }
.usecase .pill { font-size: 13px; font-weight: 700; padding: 4px 10px; border-radius: 999px; align-self: flex-start; }
.uc-sales .pill { background: #FFE6DD; color: #C73E1D; }
.uc-eng .pill { background: #DBEAFE; color: #1E40AF; }
.uc-support .pill { background: #DCFCE7; color: #15803D; }
.uc-design .pill { background: #FAE8FF; color: #86198F; }
.usecase h3 { font-size: 22px; }
.usecase p { color: var(--muted); }

/* Features list grid */
.feat-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.feat-cell { padding: 24px; border-radius: 16px; background: white; border: 1px solid var(--border); display: flex; flex-direction: column; gap: 10px; }
.feat-cell .ico {
  width: 40px; height: 40px; border-radius: 10px;
  background: var(--gradient-soft);
  display: grid; place-items: center;
}
.feat-cell h4 { font-size: 16px; }
@media (max-width: 1080px) { .feat-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .feat-grid { grid-template-columns: 1fr; } }

/* Stats */
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; text-align: center; }
.stat .num {
  font-size: clamp(3rem, 6vw, 5rem); font-weight: 800;
  background: var(--gradient); -webkit-background-clip: text; background-clip: text; color: transparent;
  letter-spacing: -0.04em; line-height: 1;
}
.stat p { color: var(--muted); margin-top: 8px; font-size: 17px; }
@media (max-width: 900px) { .stats-grid { grid-template-columns: 1fr; } }

/* Testimonials */
.test-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
@media (max-width: 1080px) { .test-grid { grid-template-columns: 1fr; } }
.testimonial {
  padding: 32px; border-radius: 20px;
  background: white; border: 1px solid var(--border);
  display: flex; flex-direction: column; gap: 20px;
}
.testimonial p.quote { font-size: 17px; line-height: 1.6; color: var(--text); }
.testimonial .author { display: flex; align-items: center; gap: 12px; margin-top: auto; }
.testimonial .avatar {
  width: 48px; height: 48px; border-radius: 50%;
  background: var(--gradient); color: white; display: grid; place-items: center;
  font-weight: 700;
}
.testimonial .name { font-weight: 700; color: var(--dark); }
.testimonial .role { font-size: 13px; color: var(--muted); }

/* CTA banner */
.cta-banner {
  border-radius: 32px; padding: 80px 48px;
  background: var(--gradient); color: white;
  text-align: center; position: relative; overflow: hidden;
}
.cta-banner::before {
  content: ""; position: absolute; inset: 0;
  background: radial-gradient(circle at 80% 20%, rgba(255,255,255,.2), transparent 50%);
}
.cta-banner h2 { color: white; margin-bottom: 16px; position: relative; }
.cta-banner p { font-size: 18px; opacity: .9; margin-bottom: 32px; position: relative; }
.cta-banner .btn { background: white; color: var(--dark); position: relative; }
.cta-banner .btn:hover { background: var(--dark); color: white; }

/* Footer */
.footer { background: #0F1018; color: #C9C9D6; padding: 80px 0 40px; }
.footer h4 { font-size: 14px; text-transform: uppercase; letter-spacing: 0.08em; color: white; margin-bottom: 18px; font-weight: 700; }
.footer-grid { display: grid; grid-template-columns: 1.5fr repeat(5, 1fr); gap: 40px; padding-bottom: 48px; border-bottom: 1px solid rgba(255,255,255,.1); }
.footer-grid ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-grid a { color: #9696A6; font-size: 14px; transition: color .15s; }
.footer-grid a:hover { color: white; }
.footer .logo { color: white; margin-bottom: 16px; }
.footer-bottom { padding-top: 32px; display: flex; justify-content: space-between; flex-wrap: wrap; gap: 16px; font-size: 13px; color: #6E6E80; }
@media (max-width: 1080px) { .footer-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .footer-grid { grid-template-columns: 1fr; } }

/* Pricing */
.billing-toggle { display: inline-flex; align-items: center; gap: 12px; background: var(--bg-soft); padding: 6px; border-radius: 999px; }
.billing-toggle button {
  padding: 10px 22px; border-radius: 999px;
  font-weight: 700; color: var(--muted); font-size: 14px;
  transition: all .2s;
}
.billing-toggle button.active { background: white; color: var(--dark); box-shadow: 0 2px 10px rgba(0,0,0,.06); }
.save-badge { display: inline-flex; padding: 4px 10px; background: #FFE6DD; color: var(--accent); border-radius: 999px; font-size: 12px; font-weight: 700; margin-left: 4px; }

.plan-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; align-items: stretch; }
@media (max-width: 1080px) { .plan-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .plan-grid { grid-template-columns: 1fr; } }
.plan {
  padding: 32px 24px; border-radius: 20px;
  background: white; border: 1px solid var(--border);
  display: flex; flex-direction: column; gap: 20px;
  position: relative;
}
.plan.popular { border-color: var(--primary); border-width: 2px; box-shadow: 0 30px 60px -20px rgba(109,91,255,.3); }
.plan-tag { position: absolute; top: -14px; left: 50%; transform: translateX(-50%); background: var(--gradient); color: white; padding: 6px 14px; border-radius: 999px; font-size: 12px; font-weight: 700; letter-spacing: 0.05em; }
.plan h3 { font-size: 20px; }
.plan .price { display: flex; align-items: baseline; gap: 4px; }
.plan .price .amount { font-size: 44px; font-weight: 800; color: var(--dark); letter-spacing: -0.03em; }
.plan .price .unit { color: var(--muted); font-size: 14px; font-weight: 600; }
.plan .desc { color: var(--muted); font-size: 14px; min-height: 42px; }
.plan ul { list-style: none; display: flex; flex-direction: column; gap: 12px; }
.plan ul li { font-size: 14px; color: var(--text); display: flex; gap: 10px; }
.plan ul li::before { content: "✓"; color: var(--primary); font-weight: 800; flex-shrink: 0; }
.plan .btn { width: 100%; }

/* Slider */
.slider-card {
  background: white; border: 1px solid var(--border);
  border-radius: 20px; padding: 28px;
  display: flex; flex-direction: column; gap: 16px; max-width: 640px; margin: 0 auto;
}
.slider-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; }
.slider-row label { font-weight: 700; }
.slider-value { font-weight: 800; color: var(--primary); font-size: 18px; }
input[type="range"] {
  -webkit-appearance: none; appearance: none;
  width: 100%; height: 6px; border-radius: 999px;
  background: linear-gradient(90deg, var(--primary) 0%, var(--primary) var(--val,30%), #E5E7EB var(--val,30%), #E5E7EB 100%);
  outline: none;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none; appearance: none;
  width: 24px; height: 24px; border-radius: 50%;
  background: white; border: 3px solid var(--primary);
  cursor: pointer; box-shadow: 0 4px 10px rgba(109,91,255,.3);
}
input[type="range"]::-moz-range-thumb {
  width: 24px; height: 24px; border-radius: 50%;
  background: white; border: 3px solid var(--primary); cursor: pointer;
}
.slider-result { font-size: 14px; color: var(--muted); padding-top: 10px; border-top: 1px solid var(--border); }
.slider-result strong { color: var(--dark); }

/* Comparison Table */
.comp-table-wrapper { overflow-x: auto; border-radius: 20px; border: 1px solid var(--border); background: white; }
.comp-table { width: 100%; border-collapse: collapse; min-width: 720px; }
.comp-table th, .comp-table td { padding: 16px 18px; text-align: left; border-bottom: 1px solid var(--border); font-size: 14px; }
.comp-table th { background: var(--bg-soft); font-weight: 700; color: var(--dark); font-size: 13px; text-transform: uppercase; letter-spacing: 0.05em; }
.comp-table td:first-child { font-weight: 600; color: var(--dark); }
.comp-table .check { color: var(--primary); font-weight: 800; }
.comp-table .dash { color: #C9C9D0; }
.comp-table tr.section-row td { background: var(--bg-tint); font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; font-size: 12px; color: var(--primary); }
.comp-collapse { max-height: 480px; overflow: hidden; transition: max-height .4s ease; position: relative; }
.comp-collapse.expanded { max-height: 4000px; }
.comp-fade { position: absolute; bottom: 0; left: 0; right: 0; height: 100px; background: linear-gradient(to top, white, transparent); pointer-events: none; transition: opacity .3s; }
.comp-collapse.expanded .comp-fade { opacity: 0; }

/* FAQ */
.faq-list { display: flex; flex-direction: column; gap: 12px; max-width: 820px; margin: 0 auto; }
.faq-item { background: white; border: 1px solid var(--border); border-radius: 14px; overflow: hidden; transition: border-color .2s; }
.faq-item.open { border-color: var(--primary); }
.faq-q { width: 100%; padding: 22px 24px; display: flex; justify-content: space-between; align-items: center; gap: 16px; font-weight: 700; font-size: 17px; text-align: left; color: var(--dark); }
.faq-q .chev { transition: transform .25s; flex-shrink: 0; color: var(--primary); font-size: 22px; line-height: 1; }
.faq-item.open .chev { transform: rotate(45deg); }
.faq-a { max-height: 0; overflow: hidden; transition: max-height .3s ease; padding: 0 24px; color: var(--muted); }
.faq-item.open .faq-a { max-height: 320px; padding-bottom: 24px; }

/* Cookie banner */
.cookie {
  position: fixed; left: 24px; right: 24px; bottom: 24px; z-index: 100;
  background: white; border: 1px solid var(--border);
  border-radius: 20px; padding: 24px;
  box-shadow: 0 30px 80px -20px rgba(0,0,0,.25);
  display: flex; gap: 24px; align-items: center;
  max-width: 920px; margin: 0 auto;
}
.cookie p { font-size: 14px; color: var(--muted); flex: 1; }
.cookie p strong { color: var(--dark); display: block; margin-bottom: 4px; font-size: 15px; }
.cookie-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.cookie-actions button { padding: 10px 18px; font-size: 14px; border-radius: 10px; font-weight: 700; }
.cookie-accept { background: var(--dark); color: white; }
.cookie-reject { background: var(--bg-soft); color: var(--dark); }
.cookie-manage { background: transparent; color: var(--primary); }
.cookie.hidden { display: none; }
@media (max-width: 720px) { .cookie { flex-direction: column; align-items: stretch; } }

/* Modal */
.modal-backdrop { position: fixed; inset: 0; background: rgba(15,16,24,.5); z-index: 200; display: none; align-items: center; justify-content: center; padding: 24px; }
.modal-backdrop.open { display: flex; }
.modal { background: white; border-radius: 20px; padding: 32px; max-width: 520px; width: 100%; box-shadow: 0 30px 80px rgba(0,0,0,.3); }
.modal h3 { margin-bottom: 8px; }
.modal > p { color: var(--muted); margin-bottom: 20px; font-size: 14px; }
.cookie-cat { display: flex; justify-content: space-between; align-items: flex-start; padding: 16px; border-radius: 12px; background: var(--bg-soft); margin-bottom: 12px; gap: 12px; }
.cookie-cat strong { display: block; margin-bottom: 4px; }
.cookie-cat span { font-size: 13px; color: var(--muted); }
.modal-foot { display: flex; gap: 12px; margin-top: 16px; }
.modal-foot .btn { flex: 1; }

/* Toggle switch */
.switch { position: relative; width: 44px; height: 24px; flex-shrink: 0; }
.switch input { opacity: 0; width: 0; height: 0; }
.switch-slider { position: absolute; inset: 0; background: #D1D5DB; border-radius: 999px; cursor: pointer; transition: .2s; }
.switch-slider::before { content: ""; position: absolute; left: 3px; top: 3px; width: 18px; height: 18px; background: white; border-radius: 50%; transition: .2s; }
.switch input:checked + .switch-slider { background: var(--primary); }
.switch input:checked + .switch-slider::before { transform: translateX(20px); }
.switch input:disabled + .switch-slider { opacity: .5; cursor: not-allowed; }

/* Auth */
.auth-shell { min-height: 100vh; display: grid; grid-template-columns: 1fr; }
.auth-shell.split { grid-template-columns: 1fr 1fr; }
@media (max-width: 900px) { .auth-shell.split { grid-template-columns: 1fr; } }
.auth-main { padding: 60px 32px; display: flex; flex-direction: column; justify-content: center; align-items: center; }
.auth-card { width: 100%; max-width: 420px; }
.auth-card h1 { font-size: 32px; margin-bottom: 24px; text-align: center; }
.auth-card .sub { text-align: center; color: var(--muted); margin-bottom: 28px; }
.social-btns { display: flex; flex-direction: column; gap: 10px; margin-bottom: 20px; }
.social-btn { width: 100%; padding: 12px 16px; border: 1px solid var(--border); border-radius: 12px; background: white; font-weight: 600; display: flex; align-items: center; gap: 12px; transition: all .2s; }
.social-btn:hover { border-color: var(--primary); background: var(--bg-tint); }
.social-btn .ico { width: 22px; height: 22px; display: grid; place-items: center; font-weight: 800; }
.divider { display: flex; align-items: center; gap: 12px; color: var(--muted); font-size: 13px; margin: 16px 0; }
.divider::before, .divider::after { content: ""; flex: 1; height: 1px; background: var(--border); }
.input-field { width: 100%; padding: 14px 16px; border: 1px solid var(--border); border-radius: 12px; font-size: 15px; font-family: inherit; transition: all .2s; }
.input-field:focus { outline: none; border-color: var(--primary); box-shadow: 0 0 0 4px rgba(109,91,255,.1); }
.auth-form { display: flex; flex-direction: column; gap: 12px; }
.auth-form button[type="submit"] { width: 100%; padding: 14px; background: var(--dark); color: white; border-radius: 12px; font-weight: 700; }
.auth-foot { font-size: 13px; color: var(--muted); margin-top: 20px; line-height: 1.5; text-align: center; }
.auth-link { color: var(--primary); font-weight: 600; }
.testimonial-side { background: var(--gradient); padding: 60px; color: white; display: flex; flex-direction: column; justify-content: center; }
.testimonial-side blockquote { font-size: 26px; font-weight: 600; line-height: 1.4; max-width: 480px; margin-bottom: 28px; }
.testimonial-side .author-block { display: flex; align-items: center; gap: 14px; }
.testimonial-side .author-block .avatar { width: 56px; height: 56px; border-radius: 50%; background: white; color: var(--primary); display: grid; place-items: center; font-weight: 800; font-size: 20px; }
.testimonial-side .author-block .name { font-weight: 700; }
.testimonial-side .author-block .role { opacity: .85; font-size: 14px; }

/* Integrations */
.integ-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 16px; }
@media (max-width: 1080px) { .integ-grid { grid-template-columns: repeat(3, 1fr); } }
.integ-cell { padding: 24px; aspect-ratio: 1; background: white; border: 1px solid var(--border); border-radius: 16px; display: grid; place-items: center; transition: all .25s; }
.integ-cell:hover { border-color: var(--primary); transform: translateY(-3px); }
.integ-cell .label { text-align: center; }
.integ-cell .ico-lg { width: 40px; height: 40px; border-radius: 8px; background: var(--gradient-soft); margin: 0 auto 8px; display: grid; place-items: center; font-weight: 800; color: var(--primary); }
.integ-cell .name { font-size: 13px; font-weight: 600; color: var(--text); }

/* Misc */
.callout {
  background: var(--gradient-soft); border: 1px solid #E8E2FF;
  border-radius: 20px; padding: 28px; display: flex; gap: 20px; align-items: center;
}
.callout .badge { background: var(--accent); color: white; padding: 4px 12px; border-radius: 999px; font-size: 12px; font-weight: 700; align-self: flex-start; }

.checks-list { list-style: none; display: flex; flex-direction: column; gap: 14px; }
.checks-list li { display: flex; gap: 12px; align-items: flex-start; }
.checks-list li::before { content: "✓"; flex-shrink: 0; width: 24px; height: 24px; border-radius: 50%; background: var(--gradient); color: white; display: grid; place-items: center; font-weight: 800; font-size: 13px; }

.blog-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
@media (max-width: 900px) { .blog-grid { grid-template-columns: 1fr; } }
.blog-card { padding: 0; border-radius: 20px; overflow: hidden; background: white; border: 1px solid var(--border); transition: all .25s; }
.blog-card:hover { transform: translateY(-3px); box-shadow: 0 20px 50px -20px rgba(0,0,0,.18); }
.blog-thumb { aspect-ratio: 16/9; background: var(--gradient); position: relative; }
.blog-thumb::after { content: ""; position: absolute; inset: 0; background: radial-gradient(circle at 70% 30%, rgba(255,255,255,.3), transparent 60%); }
.blog-body { padding: 24px; }
.blog-body .tag { font-size: 12px; font-weight: 700; color: var(--primary); text-transform: uppercase; letter-spacing: 0.05em; }
.blog-body h3 { font-size: 20px; margin: 8px 0; }
.blog-body p { color: var(--muted); font-size: 14px; }

/* Carousel */
.carousel { overflow: hidden; }
.carousel-track { display: flex; gap: 24px; transition: transform .4s ease; }
.carousel-card { flex: 0 0 calc(33.333% - 16px); }
@media (max-width: 1080px) { .carousel-card { flex: 0 0 calc(50% - 12px); } }
@media (max-width: 720px) { .carousel-card { flex: 0 0 100%; } }
.carousel-controls { display: flex; gap: 10px; justify-content: center; margin-top: 28px; }
.carousel-controls button { width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--border); background: white; font-size: 18px; transition: all .2s; }
.carousel-controls button:hover { background: var(--dark); color: white; border-color: var(--dark); }

